<?php
namespace App\Domains\Communication\Http\Controllers;
use App\Domains\Communication\Models\{CommunicationDelivery,CommunicationPreference,CommunicationTemplate}; use App\Domains\Communication\Services\CommunicationService; use App\Domains\Platform\Contracts\TenantContext; use Illuminate\Http\{JsonResponse,Request};
class CommunicationController { public function __construct(private readonly CommunicationService $service,private readonly TenantContext $tenant){} private function allow(Request $r,string $p):void{$r->user()->hasPermission($p)||abort(403);} public function templates(Request $r):JsonResponse{$this->allow($r,'communications.view');return response()->json(['data'=>CommunicationTemplate::query()->where(fn($q)=>$q->whereNull('tenant_id')->orWhere('tenant_id',$this->tenant->id()))->paginate(25)]);} public function createTemplate(Request $r):JsonResponse{$this->allow($r,'communications.manage');$d=$r->validate(['key'=>['required','alpha_dash'],'name'=>['required','string'],'channel'=>['required','in:in_app,email,sms,whatsapp,push'],'locale'=>['nullable','string'],'subject'=>['nullable','string'],'body'=>['required','string'],'status'=>['sometimes','in:draft,approved,published']]);return response()->json(['data'=>CommunicationTemplate::query()->create([...$d,'tenant_id'=>$this->tenant->id()])],201);} public function send(Request $r):JsonResponse{$this->allow($r,'communications.send');$d=$r->validate(['channel'=>['required','string'],'notification_type'=>['required','string'],'recipient'=>['required','string'],'subject'=>['nullable','string'],'body'=>['required','string'],'variables'=>['nullable','array'],'user_id'=>['nullable','integer'],'scheduled_at'=>['nullable','date']]);$body=$this->service->render($d['body'],$d['variables']??[]);unset($d['variables']);$d['body']=$body;return response()->json(['data'=>$this->service->queue($this->tenant->id(),$d)],202);} public function inbox(Request $r):JsonResponse{$this->allow($r,'communications.view');return response()->json(['data'=>CommunicationDelivery::query()->where('tenant_id',$this->tenant->id())->where('user_id',$r->user()->id)->latest()->paginate(25)]);} public function preference(Request $r):JsonResponse{$this->allow($r,'communications.manage');$d=$r->validate(['channels'=>['required','array'],'locale'=>['nullable','string'],'timezone'=>['nullable','string'],'quiet_start'=>['nullable','date_format:H:i'],'quiet_end'=>['nullable','date_format:H:i']]);return response()->json(['data'=>CommunicationPreference::query()->updateOrCreate(['tenant_id'=>$this->tenant->id(),'user_id'=>$r->user()->id],$d)]);} public function track(Request $r,string $delivery):JsonResponse{$this->allow($r,'communications.send');$status=$r->validate(['status'=>['required','in:sent,delivered,read,failed,bounced,unsubscribed']])['status'];return response()->json(['data'=>$this->service->mark($this->tenant->id(),$delivery,$status)]);} }
